13	`timescale 1ns/1ns
14	//`include "fpu_ops.v"
15	`include "define.v"
16	`define CTRLGEN
17	
18	module scalar_fpu #(
19	  parameter EXPWIDTH    = 8,
20	  parameter PRECISION   = 24,
21	  parameter SOFT_THREAD = 4,
22	  parameter HARD_THREAD = 4
23	)(
24	  input                                         clk            ,
25	  input                                         rst_n          ,
26	
27	  input      [5:0]                              op_i           ,
28	  input      [EXPWIDTH+PRECISION-1:0]           a_i            ,
29	  input      [EXPWIDTH+PRECISION-1:0]           b_i            ,
30	  input      [EXPWIDTH+PRECISION-1:0]           c_i            ,
31	  input      [2:0]                              rm_i           ,
32	`ifdef CTRLGEN
