44	  output reg                                    out_valid_o    ,
45	
46	  output     [2:0]                              select_o       ,
47	  output reg [63:0]                             result_o       ,
48	  output reg [4:0]                              fflags_o       
49	`ifdef CTRLGEN
50	                                                               ,
51	  output reg [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]  ctrl_regindex_o,
52	  output reg [`DEPTH_WARP-1:0]                  ctrl_warpid_o  ,
53	  output reg [SOFT_THREAD-1:0]                  ctrl_vecmask_o ,
54	  output reg                                    ctrl_wvd_o     ,
55	  output reg                                    ctrl_wxd_o     
56	`endif
57	  );
58	
59	  wire    [2:0]                             fu             ;
60	  wire    [4:0]                             choose_oh      ;
61	  wire    [2:0]                             choose_bin     ;
62	  
63	  //fma 
64	  wire    [2:0]                             fma_op_in      ;
65	  wire    [2:0]                             fma_rm_in      ;
66	  wire    [EXPWIDTH+PRECISION-1:0]          fma_a_in       ;
67	  wire    [EXPWIDTH+PRECISION-1:0]          fma_b_in       ;
68	  wire    [EXPWIDTH+PRECISION-1:0]          fma_c_in       ;
69	  wire                                      fma_in_valid   ;
70	  wire                                      fma_out_ready  ;
71	  wire                                      fma_in_ready   ;
72	  wire                                      fma_out_valid  ;
73	  wire    [EXPWIDTH+PRECISION-1:0]          fma_result_out ;
74	  wire    [4:0]                             fma_fflags_out ;
75	`ifdef CTRLGEN
76	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] fma_ctrl_regindex_in ;
77	  wire    [`DEPTH_WARP-1:0]                 fma_ctrl_warpid_in   ;
78	  wire    [SOFT_THREAD-1:0]                 fma_ctrl_vecmask_in  ;
79	  wire                                      fma_ctrl_wvd_in      ;
80	  wire                                      fma_ctrl_wxd_in      ;
81	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] fma_ctrl_regindex_out;
82	  wire    [`DEPTH_WARP-1:0]                 fma_ctrl_warpid_out  ;
83	  wire    [SOFT_THREAD-1:0]                 fma_ctrl_vecmask_out ;
84	  wire                                      fma_ctrl_wvd_out     ;
85	  wire                                      fma_ctrl_wxd_out     ;
86	`endif
87	
88	  //fcmp
89	  wire    [2:0]                             fcmp_op_in      ;
90	  //wire    [2:0]                             fcmp_rm_in      ;
91	  wire    [EXPWIDTH+PRECISION-1:0]          fcmp_a_in       ;
92	  wire    [EXPWIDTH+PRECISION-1:0]          fcmp_b_in       ;
93	  //wire    [EXPWIDTH+PRECISION-1:0]          fcmp_c_in       ;
94	  wire                                      fcmp_in_valid   ;
95	  wire                                      fcmp_out_ready  ;
96	  wire                                      fcmp_in_ready   ;
97	  wire                                      fcmp_out_valid  ;
98	  wire    [EXPWIDTH+PRECISION-1:0]          fcmp_result_out ;
99	  wire    [4:0]                             fcmp_fflags_out ;
100	`ifdef CTRLGEN
101	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] fcmp_ctrl_regindex_in ;
102	  wire    [`DEPTH_WARP-1:0]                 fcmp_ctrl_warpid_in   ;
103	  wire    [SOFT_THREAD-1:0]                 fcmp_ctrl_vecmask_in  ;
104	  wire                                      fcmp_ctrl_wvd_in      ;
105	  wire                                      fcmp_ctrl_wxd_in      ;
106	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] fcmp_ctrl_regindex_out;
107	  wire    [`DEPTH_WARP-1:0]                 fcmp_ctrl_warpid_out  ;
108	  wire    [SOFT_THREAD-1:0]                 fcmp_ctrl_vecmask_out ;
109	  wire                                      fcmp_ctrl_wvd_out     ;
110	  wire                                      fcmp_ctrl_wxd_out     ;
111	`endif
112	
113	  //fpmv
114	  wire    [2:0]                             fpmv_op_in      ;
115	  //wire    [2:0]                             fpmv_rm_in      ;
116	  wire    [EXPWIDTH+PRECISION-1:0]          fpmv_a_in       ;
117	  wire    [EXPWIDTH+PRECISION-1:0]          fpmv_b_in       ;
118	  //wire    [EXPWIDTH+PRECISION-1:0]          fpmv_c_in       ;
119	  wire                                      fpmv_in_valid   ;
120	  wire                                      fpmv_out_ready  ;
121	  wire                                      fpmv_in_ready   ;
122	  wire                                      fpmv_out_valid  ;
123	  wire    [EXPWIDTH+PRECISION-1:0]          fpmv_result_out ;
124	  wire    [4:0]                             fpmv_fflags_out ;
125	`ifdef CTRLGEN
126	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] fpmv_ctrl_regindex_in ;
127	  wire    [`DEPTH_WARP-1:0]                 fpmv_ctrl_warpid_in   ;
128	  wire    [SOFT_THREAD-1:0]                 fpmv_ctrl_vecmask_in  ;
129	  wire                                      fpmv_ctrl_wvd_in      ;
130	  wire                                      fpmv_ctrl_wxd_in      ;
131	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] fpmv_ctrl_regindex_out;
132	  wire    [`DEPTH_WARP-1:0]                 fpmv_ctrl_warpid_out  ;
133	  wire    [SOFT_THREAD-1:0]                 fpmv_ctrl_vecmask_out ;
134	  wire                                      fpmv_ctrl_wvd_out     ;
135	  wire                                      fpmv_ctrl_wxd_out     ;
136	`endif
137	
138	  //fp_to_int
139	  wire    [2:0]                             f2i_op_in        ;
140	  wire    [2:0]                             f2i_rm_in        ;
141	  wire    [EXPWIDTH+PRECISION-1:0]          f2i_a_in         ;
142	  wire    [63:0]                            f2i_a_in_64      ;
143	  //wire    [EXPWIDTH+PRECISION-1:0]          f2i_b_in         ;
144	  //wire    [EXPWIDTH+PRECISION-1:0]          f2i_c_in         ;
145	  wire                                      f2i_in_valid     ;
146	  wire                                      f2i_out_ready    ;
147	  wire                                      f2i_in_ready     ;
148	  wire                                      f2i_out_valid    ;
149	  wire    [EXPWIDTH+PRECISION-1:0]          f2i_result_out   ;
150	  wire    [63:0]                            f2i_result_out_64;
151	  wire    [4:0]                             f2i_fflags_out   ;
152	`ifdef CTRLGEN
153	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] f2i_ctrl_regindex_in ;
154	  wire    [`DEPTH_WARP-1:0]                 f2i_ctrl_warpid_in   ;
155	  wire    [SOFT_THREAD-1:0]                 f2i_ctrl_vecmask_in  ;
156	  wire                                      f2i_ctrl_wvd_in      ;
157	  wire                                      f2i_ctrl_wxd_in      ;
158	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] f2i_ctrl_regindex_out;
159	  wire    [`DEPTH_WARP-1:0]                 f2i_ctrl_warpid_out  ;
160	  wire    [SOFT_THREAD-1:0]                 f2i_ctrl_vecmask_out ;
161	  wire                                      f2i_ctrl_wvd_out     ;
162	  wire                                      f2i_ctrl_wxd_out     ;
163	`endif
164	
165	  //int_to_fp
166	  wire    [2:0]                             i2f_op_in        ;
167	  wire    [2:0]                             i2f_rm_in        ;
168	  wire    [EXPWIDTH+PRECISION-1:0]          i2f_a_in         ;
169	  wire    [63:0]                            i2f_a_in_64      ;
170	  //wire    [EXPWIDTH+PRECISION-1:0]          i2f_b_in         ;
171	  //wire    [EXPWIDTH+PRECISION-1:0]          i2f_c_in         ;
172	  wire                                      i2f_in_valid     ;
173	  wire                                      i2f_out_ready    ;
174	  wire                                      i2f_in_ready     ;
175	  wire                                      i2f_out_valid    ;
176	  wire    [EXPWIDTH+PRECISION-1:0]          i2f_result_out   ;
177	  wire    [63:0]                            i2f_result_out_64;
178	  wire    [4:0]                             i2f_fflags_out   ;
179	`ifdef CTRLGEN
180	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] i2f_ctrl_regindex_in ;
181	  wire    [`DEPTH_WARP-1:0]                 i2f_ctrl_warpid_in   ;
182	  wire    [SOFT_THREAD-1:0]                 i2f_ctrl_vecmask_in  ;
183	  wire                                      i2f_ctrl_wvd_in      ;
184	  wire                                      i2f_ctrl_wxd_in      ;
185	  wire    [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] i2f_ctrl_regindex_out;
186	  wire    [`DEPTH_WARP-1:0]                 i2f_ctrl_warpid_out  ;
187	  wire    [SOFT_THREAD-1:0]                 i2f_ctrl_vecmask_out ;
188	  wire                                      i2f_ctrl_wvd_out     ;
189	  wire                                      i2f_ctrl_wxd_out     ;
190	`endif
191	
192	  //fma input
193	  assign fu                   = op_i[5:3];
194	  assign fma_op_in            = (fu == 'd0) ? op_i[2:0] : 'd0; 
195	  assign fma_rm_in            = (fu == 'd0) ? rm_i      : 'd0;
196	  assign fma_a_in             = (fu == 'd0) ? a_i       : 'd0;
197	  assign fma_b_in             = (fu == 'd0) ? b_i       : 'd0;
198	  assign fma_c_in             = (fu == 'd0) ? c_i       : 'd0;
199	  assign fma_in_valid         = (fu == 'd0) && in_valid_i    ;
200	  assign fma_out_ready        = out_ready_i                  ;  
201	`ifdef CTRLGEN
202	  assign fma_ctrl_regindex_in = (fu == 'd0) ? ctrl_regindex_i : 'd0;
203	  assign fma_ctrl_warpid_in   = (fu == 'd0) ? ctrl_warpid_i   : 'd0;
204	  assign fma_ctrl_vecmask_in  = (fu == 'd0) ? ctrl_vecmask_i  : 'd0;
205	  assign fma_ctrl_wvd_in      = (fu == 'd0) ? ctrl_wvd_i      : 'd0;
206	  assign fma_ctrl_wxd_in      = (fu == 'd0) ? ctrl_wxd_i      : 'd0;
207	`endif
208	
209	  //fcmp input
210	  assign fcmp_op_in            = (fu == 'd1) ? op_i[2:0] : 'd0; 
211	  //assign fcmp_rm_in            = (fu == 'd1) ? rm_i      : 'd0;
212	  assign fcmp_a_in             = (fu == 'd1) ? a_i       : 'd0;
213	  assign fcmp_b_in             = (fu == 'd1) ? b_i       : 'd0;
214	  //assign fcmp_c_in             = (fu == 'd1) ? c_i       : 'd0;
215	  assign fcmp_in_valid         = (fu == 'd1) && in_valid_i    ;
216	  assign fcmp_out_ready        = out_ready_i                  ;  
217	`ifdef CTRLGEN
218	  assign fcmp_ctrl_regindex_in = (fu == 'd1) ? ctrl_regindex_i : 'd0;
219	  assign fcmp_ctrl_warpid_in   = (fu == 'd1) ? ctrl_warpid_i   : 'd0;
220	  assign fcmp_ctrl_vecmask_in  = (fu == 'd1) ? ctrl_vecmask_i  : 'd0;
221	  assign fcmp_ctrl_wvd_in      = (fu == 'd1) ? ctrl_wvd_i      : 'd0;
222	  assign fcmp_ctrl_wxd_in      = (fu == 'd1) ? ctrl_wxd_i      : 'd0;
223	`endif
224	
225	  //fpmv input
