228	  assign fpmv_a_in             = (fu == 'd2) ? a_i       : 'd0;
229	  assign fpmv_b_in             = (fu == 'd2) ? b_i       : 'd0;
230	  //assign fpmv_c_in             = (fu == 'd2) ? c_i       : 'd0;
231	  assign fpmv_in_valid         = (fu == 'd2) && in_valid_i    ;
232	  assign fpmv_out_ready        = out_ready_i                  ;  
233	`ifdef CTRLGEN
234	  assign fpmv_ctrl_regindex_in = (fu == 'd2) ? ctrl_regindex_i : 'd0;
235	  assign fpmv_ctrl_warpid_in   = (fu == 'd2) ? ctrl_warpid_i   : 'd0;
236	  assign fpmv_ctrl_vecmask_in  = (fu == 'd2) ? ctrl_vecmask_i  : 'd0;
237	  assign fpmv_ctrl_wvd_in      = (fu == 'd2) ? ctrl_wvd_i      : 'd0;
238	  assign fpmv_ctrl_wxd_in      = (fu == 'd2) ? ctrl_wxd_i      : 'd0;
239	`endif
240	
241	  //f2i input
242	  assign f2i_op_in            = (fu == 'd3) ? op_i[2:0] : 'd0             ; 
243	  assign f2i_rm_in            = (fu == 'd3) ? rm_i      : 'd0             ;
244	  assign f2i_a_in             = (fu == 'd3) ? a_i       : 'd0             ;
245	  assign f2i_a_in_64          = {{(64-EXPWIDTH-PRECISION){1'b0}},f2i_a_in};
246	  //assign f2i_b_in             = (fu == 'd3) ? b_i       : 'd0             ;
247	  //assign f2i_c_in             = (fu == 'd3) ? c_i       : 'd0             ;
248	  assign f2i_in_valid         = (fu == 'd3) && in_valid_i                 ;
249	  assign f2i_out_ready        = out_ready_i                               ;  
250	`ifdef CTRLGEN
251	  assign f2i_ctrl_regindex_in = (fu == 'd3) ? ctrl_regindex_i : 'd0;
252	  assign f2i_ctrl_warpid_in   = (fu == 'd3) ? ctrl_warpid_i   : 'd0;
253	  assign f2i_ctrl_vecmask_in  = (fu == 'd3) ? ctrl_vecmask_i  : 'd0;
254	  assign f2i_ctrl_wvd_in      = (fu == 'd3) ? ctrl_wvd_i      : 'd0;
255	  assign f2i_ctrl_wxd_in      = (fu == 'd3) ? ctrl_wxd_i      : 'd0;
256	`endif
257	
258	  //i2f input
259	  assign i2f_op_in            = (fu == 'd4) ? op_i[2:0] : 'd0             ; 
260	  assign i2f_rm_in            = (fu == 'd4) ? rm_i      : 'd0             ;
261	  assign i2f_a_in             = (fu == 'd4) ? a_i       : 'd0             ;
262	  assign i2f_a_in_64          = {{(64-EXPWIDTH-PRECISION){1'b0}},i2f_a_in};
263	  //assign i2f_b_in             = (fu == 'd4) ? b_i       : 'd0             ;
264	  //assign i2f_c_in             = (fu == 'd4) ? c_i       : 'd0             ;
265	  assign i2f_in_valid         = (fu == 'd4) && in_valid_i                 ;
266	  assign i2f_out_ready        = out_ready_i                               ;  
267	`ifdef CTRLGEN
268	  assign i2f_ctrl_regindex_in = (fu == 'd4) ? ctrl_regindex_i : 'd0;
269	  assign i2f_ctrl_warpid_in   = (fu == 'd4) ? ctrl_warpid_i   : 'd0;
270	  assign i2f_ctrl_vecmask_in  = (fu == 'd4) ? ctrl_vecmask_i  : 'd0;
271	  assign i2f_ctrl_wvd_in      = (fu == 'd4) ? ctrl_wvd_i      : 'd0;
272	  assign i2f_ctrl_wxd_in      = (fu == 'd4) ? ctrl_wxd_i      : 'd0;
273	`endif
274	
275	  //例化fma
276	  fma #(
277	    .EXPWIDTH(EXPWIDTH),
278	    .PRECISION(PRECISION),
279	    .SOFTTHREAD(SOFT_THREAD),
280	    .HARDTHREAD(HARD_THREAD)
281	  )
