325	    .out_valid_o    (fcmp_out_valid        ),                                 
326	`ifdef CTRLGEN
327	    .ctrl_regindex_i(fcmp_ctrl_regindex_in ),               
328	    .ctrl_warpid_i  (fcmp_ctrl_warpid_in   ),                       
329	    .ctrl_vecmask_i (fcmp_ctrl_vecmask_in  ),          
