333	    .ctrl_warpid_o  (fcmp_ctrl_warpid_out  ),                          
334	    .ctrl_vecmask_o (fcmp_ctrl_vecmask_out ),                         
335	    .ctrl_wvd_o     (fcmp_ctrl_wvd_out     ),                       
336	    .ctrl_wxd_o     (fcmp_ctrl_wxd_out     ),                     
337	`endif
338	    .result_o       (fcmp_result_out       ),               
339	    .fflags_o       (fcmp_fflags_out       )
340	    );
341	
342	  //例化fpmv
343	  fpmv #(
344	    .EXPWIDTH(EXPWIDTH),
345	    .PRECISION(PRECISION),
346	    .SOFT_THREAD(SOFT_THREAD)
347	  )
348	  U_fpmv (
