366	    .ctrl_vecmask_o (fpmv_ctrl_vecmask_out ),                         
367	    .ctrl_wvd_o     (fpmv_ctrl_wvd_out     ),                       
368	    .ctrl_wxd_o     (fpmv_ctrl_wxd_out     ),                     
369	`endif
370	    .result_o       (fpmv_result_out       ),               
371	    .fflags_o       (fpmv_fflags_out       )
372	    );
373	
