375	  fp_to_int #(
376	    .EXPWIDTH(EXPWIDTH),
377	    .PRECISION(PRECISION),
378	    .SOFT_THREAD(SOFT_THREAD)
379	  )
380	  U_f2i (
381	    .clk            (clk                  ),                    
382	    .rst_n          (rst_n                ), 
383	    .op_i           (f2i_op_in            ),  
384	    .a_i            (f2i_a_in_64          ),     
385	    .rm_i           (f2i_rm_in            ),             
386	    .in_valid_i     (f2i_in_valid         ),                   
387	    .in_ready_o     (f2i_in_ready         ),                   
388	    .out_ready_i    (f2i_out_ready        ),                    
389	    .out_valid_o    (f2i_out_valid        ),                                 
390	`ifdef CTRLGEN
391	    .ctrl_regindex_i(f2i_ctrl_regindex_in ),               
392	    .ctrl_warpid_i  (f2i_ctrl_warpid_in   ),                       
393	    .ctrl_vecmask_i (f2i_ctrl_vecmask_in  ),          
394	    .ctrl_wvd_i     (f2i_ctrl_wvd_in      ),              
