539	        ctrl_vecmask_o  = i2f_ctrl_vecmask_out ;
540	        ctrl_wvd_o      = i2f_ctrl_wvd_out     ;
541	        ctrl_wxd_o      = i2f_ctrl_wxd_out     ;
