21	module fma #(
22	  parameter EXPWIDTH  = 8 ,
23	  parameter PRECISION = 24,
24	  parameter SOFTTHREAD= 4 ,
25	  parameter HARDTHREAD= 4 
26	)
27	(
28	  input                                clk                       ,
29	  input                                rst_n                     ,
30	  input                                in_valid_i                ,
31	  output                               in_ready_o                ,
32	  input  [2:0]                         in_op_i                   ,
33	  input  [EXPWIDTH+PRECISION-1:0]      in_a_i                    ,
34	  input  [EXPWIDTH+PRECISION-1:0]      in_b_i                    ,
35	  input  [EXPWIDTH+PRECISION-1:0]      in_c_i                    ,
36	  input  [2:0]                         in_rm_i                   ,
37	`ifdef CTRLGEN
38	  input  [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] in_reg_index_i        ,
39	  input  [`DEPTH_WARP-1:0]                 in_warp_id_i          ,
40	  input  [SOFTTHREAD-1:0]                  in_vec_mask_i         ,
41	  input                                    in_wvd_i              ,
42	  input                                    in_wxd_i              ,
43	  output [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] out_reg_index_o       ,
44	  output [`DEPTH_WARP-1:0]                 out_warp_id_o         ,
45	  output [SOFTTHREAD-1:0]                  out_vec_mask_o        ,
46	  output                                   out_wvd_o             ,
47	  output                                   out_wxd_o             ,
48	`endif
49	  output                               out_valid_o               ,
