52	  output [4:0]                         out_fflags_o               
53	);
54	
55	  parameter LEN = EXPWIDTH + PRECISION;
56	
57	  //mul_pipe
58	  wire is_fma            ;
59	  wire is_fmul           ;
60	  wire is_addsub         ;
61	  wire mul_pipe_in_valid ;
62	
63	  assign is_fma            = in_op_i[2] == 1'b1               ;
64	  assign is_fmul           = in_op_i == 3'b010                ;
65	  assign is_addsub         = in_op_i[2:1] == 2'b00            ;
66	  assign mul_pipe_in_valid = in_valid_i && (is_fma || is_fmul);
67	
68	  wire                                   mul_in_ready           ;
69	`ifdef CTRLGEN
70	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] mul_out_reg_index      ;
71	  wire [`DEPTH_WARP-1:0]                 mul_out_warp_id        ;
72	  wire [SOFTTHREAD-1:0]                  mul_out_vec_mask       ;
73	  wire                                   mul_out_wvd            ;
74	  wire                                   mul_out_wxd            ;
75	  wire [4:0]                             ctrl_w_ready_o         ;
76	  wire [4:0]                             ctrl_r_valid_o         ;
77	`endif
78	  wire                                   mul_out_valid          ;
79	  wire                                   mul_out_ready          ;
80	  wire [EXPWIDTH+PRECISION-1:0]          mul_out_result         ;
81	  wire [4:0]                             mul_out_fflags         ;
82	  wire                                   mul_toadd_fp_prod_sign ;
83	  wire [EXPWIDTH-1:0]                    mul_toadd_fp_prod_exp  ;
84	  wire [2*PRECISION-2:0]                 mul_toadd_fp_prod_sig  ;
85	  wire                                   mul_toadd_is_nan       ;
86	  wire                                   mul_toadd_is_inf       ;
87	  wire                                   mul_toadd_is_inv       ;
88	  wire                                   mul_toadd_overflow     ;
89	  wire [EXPWIDTH+PRECISION-1:0]          mul_toadd_add_another  ;
90	  wire [2:0]                             mul_toadd_op           ;
91	
92	
93	  fmul_pipe #(
94	    .EXPWIDTH   (EXPWIDTH  ),
95	    .PRECISION  (PRECISION ),
96	    .SOFTTHREAD (SOFTTHREAD),
97	    .HARDTHREAD (HARDTHREAD)
98	  )
99	  mul_pipe (
100	    .clk                       (clk                   ),
101	    .rst_n                     (rst_n                 ),
102	    .in_valid_i                (mul_pipe_in_valid     ),
103	    .in_ready_o                (mul_in_ready          ),
104	    .in_op_i                   (in_op_i               ),
105	    .in_a_i                    (in_a_i                ),
106	    .in_b_i                    (in_b_i                ),
107	    .in_c_i                    (in_c_i                ),
108	    .in_rm_i                   (in_rm_i               ),
109	`ifdef CTRLGEN
110	    .in_reg_index_i            (in_reg_index_i        ),
111	    .in_warp_id_i              (in_warp_id_i          ),
112	    .in_vec_mask_i             (in_vec_mask_i         ),
113	    .in_wvd_i                  (in_wvd_i              ),
114	    .in_wxd_i                  (in_wxd_i              ),
115	    .out_reg_index_o           (mul_out_reg_index     ),
116	    .out_warp_id_o             (mul_out_warp_id       ),
117	    .out_vec_mask_o            (mul_out_vec_mask      ),
118	    .out_wvd_o                 (mul_out_wvd           ),
119	    .out_wxd_o                 (mul_out_wxd           ),
120	`endif
121	    .out_valid_o               (mul_out_valid         ),
122	    .out_ready_i               (mul_out_ready         ),
123	    .out_result_o              (mul_out_result        ),
124	    .out_fflags_o              (mul_out_fflags        ),
125	    .mul_output_fp_prod_sign_o (mul_toadd_fp_prod_sign),
126	    .mul_output_fp_prod_exp_o  (mul_toadd_fp_prod_exp ),
127	    .mul_output_fp_prod_sig_o  (mul_toadd_fp_prod_sig ),
128	    .mul_output_is_nan_o       (mul_toadd_is_nan      ),
129	    .mul_output_is_inf_o       (mul_toadd_is_inf      ),
130	    .mul_output_is_inv_o       (mul_toadd_is_inv      ),
131	    .mul_output_overflow_o     (mul_toadd_overflow    ),
132	    .add_another_o             (mul_toadd_add_another ),
133	    .op_o                      (mul_toadd_op          )
134	  );
135	
136	  //toadd arb: include fifo(0) and fifo(1)
137	  wire       toaddarb_fifo_0_enq_ready ;
138	  wire       toaddarb_fifo_0_deq_valid ;
139	  wire       toaddarb_fifo_0_deq_ready ;
140	  wire [2:0] toaddarb_fifo_0_deq_op    ;
141	`ifdef CTRLGEN
142	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:0] toaddarb_fifo_0_enq_ctrl;
143	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:0] toaddarb_fifo_0_deq_ctrl;
144	  
145	  assign toaddarb_fifo_0_enq_ctrl = {mul_out_reg_index,mul_out_warp_id,mul_out_vec_mask,mul_out_wvd,mul_out_wxd};
146	`endif
147	  
148	  wire       toaddarb_fifo_1_enq_valid ;
149	  wire       toaddarb_fifo_1_enq_ready ;
150	  wire       toaddarb_fifo_1_deq_valid ;
151	  wire       toaddarb_fifo_1_deq_ready ;
152	  wire [2:0] toaddarb_fifo_1_deq_op    ;
153	`ifdef CTRLGEN
154	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:0] toaddarb_fifo_1_enq_ctrl;
155	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:0] toaddarb_fifo_1_deq_ctrl;
156	  
157	  assign toaddarb_fifo_1_enq_ctrl = {in_reg_index_i,in_warp_id_i,in_vec_mask_i,in_wvd_i,in_wxd_i};
158	`endif
159	
160	  wire   mul_toadd_isfma;
161	
162	  assign mul_toadd_isfma = mul_toadd_op[2] == 1'b1;
163	
164	  //fifo(0): for mul-arb-add
165	  stream_fifo_pipe_true #(
166	    .DATA_WIDTH (3),
167	    .FIFO_DEPTH (1)
168	  )
169	  to_add_arb_fifo_0_op (
