174	    .w_data_i  (mul_toadd_op                    ),
175	    .r_valid_o (toaddarb_fifo_0_deq_valid       ),
176	    .r_ready_i (toaddarb_fifo_0_deq_ready       ),
177	    .r_data_o  (toaddarb_fifo_0_deq_op          )
178	  );
179	
180	`ifdef CTRLGEN
181	  stream_fifo_pipe_true #(
182	    .DATA_WIDTH (`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+2),
183	    .FIFO_DEPTH (1                                                    )
184	  )
185	  to_add_arb_fifo_0_ctrl (
186	    .clk       (clk                             ),
187	    .rst_n     (rst_n                           ),
188	    .w_ready_o (ctrl_w_ready_o[0]               ),    
189	    .w_valid_i (mul_out_valid && mul_toadd_isfma),
190	    .w_data_i  (toaddarb_fifo_0_enq_ctrl        ),
191	    .r_valid_o (ctrl_r_valid_o[0]               ),
192	    .r_ready_i (toaddarb_fifo_0_deq_ready       ),
193	    .r_data_o  (toaddarb_fifo_0_deq_ctrl        )
194	  );
195	`endif
