197	  //fifo(1): for input-arb-add
198	  stream_fifo_pipe_true #(
199	    .DATA_WIDTH (3),
200	    .FIFO_DEPTH (1)
201	  )
202	  to_add_arb_fifo_1_op (
203	    .clk       (clk                      ),
204	    .rst_n     (rst_n                    ),
205	    .w_ready_o (toaddarb_fifo_1_enq_ready),    
206	    .w_valid_i (in_valid_i && is_addsub  ),
207	    .w_data_i  (in_op_i                  ),
208	    .r_valid_o (toaddarb_fifo_1_deq_valid),
209	    .r_ready_i (toaddarb_fifo_1_deq_ready),
210	    .r_data_o  (toaddarb_fifo_1_deq_op   )
211	  );
212	
213	`ifdef CTRLGEN
214	  stream_fifo_pipe_true #(
215	    .DATA_WIDTH (`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+2),
216	    .FIFO_DEPTH (1                                                    )
217	  )
218	  to_add_arb_fifo_1_ctrl (
219	    .clk       (clk                      ),
220	    .rst_n     (rst_n                    ),
221	    .w_ready_o (ctrl_w_ready_o[1]        ),    
222	    .w_valid_i (in_valid_i && is_addsub  ),
223	    .w_data_i  (toaddarb_fifo_1_enq_ctrl ),
224	    .r_valid_o (ctrl_r_valid_o[1]        ),
225	    .r_ready_i (toaddarb_fifo_1_deq_ready),
226	    .r_data_o  (toaddarb_fifo_1_deq_ctrl )
227	  );
228	`endif
