231	  wire       toaddarb_out_valid;
232	  wire       toaddarb_out_ready;
233	  wire [2:0] toaddarb_out_op   ;
234	
235	  assign toaddarb_out_valid        = toaddarb_fifo_0_deq_valid || toaddarb_fifo_1_deq_valid                     ;
236	  assign toaddarb_fifo_0_deq_ready = toaddarb_out_ready                                                         ;
237	  assign toaddarb_fifo_1_deq_ready = !toaddarb_fifo_0_deq_valid && toaddarb_out_ready                           ;
238	  assign toaddarb_out_op           = toaddarb_fifo_0_deq_valid ? toaddarb_fifo_0_deq_op : toaddarb_fifo_1_deq_op;
239	`ifdef CTRLGEN
240	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:0] toaddarb_out_ctrl;
241	
242	  assign toaddarb_out_ctrl = toaddarb_fifo_0_deq_valid ? toaddarb_fifo_0_deq_ctrl : toaddarb_fifo_1_deq_ctrl    ;
243	`endif
244	  
245	  //in to add fifo
246	  wire             intoadd_enq_ready;
247	  wire             intoadd_deq_valid;
