249	  wire [LEN*3+5:0] intoadd_deq_bits ;
250	
251	  assign intoadd_enq_bits = {in_op_i,in_a_i,in_b_i,in_c_i,in_rm_i};
252	  
253	  stream_fifo_pipe_true #(
254	    .DATA_WIDTH (LEN*3+6),
255	    .FIFO_DEPTH (1      )
256	  )
257	  intoadd_fifo_bits (
258	    .clk       (clk                      ),
259	    .rst_n     (rst_n                    ),
260	    .w_ready_o (intoadd_enq_ready        ),    
261	    .w_valid_i (in_valid_i && is_addsub  ),
262	    .w_data_i  (intoadd_enq_bits         ),
263	    .r_valid_o (intoadd_deq_valid        ),
264	    .r_ready_i (toaddarb_fifo_1_deq_ready),
265	    .r_data_o  (intoadd_deq_bits         )
266	  );
267	
268	`ifdef CTRLGEN
269	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:0] intoadd_deq_ctrl;
270	
271	  stream_fifo_pipe_true #(
272	    .DATA_WIDTH (`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+2),
273	    .FIFO_DEPTH (1                                                    )
274	  )
275	  intoadd_fifo_ctrl (
276	    .clk       (clk                      ),
277	    .rst_n     (rst_n                    ),
278	    .w_ready_o (ctrl_w_ready_o[2]        ),    
279	    .w_valid_i (in_valid_i && is_addsub  ),
280	    .w_data_i  (toaddarb_fifo_1_enq_ctrl ),
281	    .r_valid_o (ctrl_r_valid_o[2]        ),
282	    .r_ready_i (toaddarb_fifo_1_deq_ready),
283	    .r_data_o  (intoadd_deq_ctrl         )
284	  );
285	`endif
286	
287	  //mul to add fifo
288	  wire                       multoadd_enq_valid;
289	  wire                       multoadd_enq_ready;
290	  wire                       multoadd_deq_valid;
291	  wire                       multoadd_deq_ready;
292	  wire [LEN*2+PRECISION+6:0] multoadd_enq_bits ;
293	  wire [LEN*2+PRECISION+6:0] multoadd_deq_bits ;
294	
295	  assign multoadd_enq_valid = toaddarb_fifo_0_enq_ready && (mul_out_valid && mul_toadd_isfma);
296	  assign multoadd_deq_ready = toaddarb_fifo_0_deq_ready && toaddarb_fifo_0_deq_valid         ;
297	  assign multoadd_enq_bits  = {mul_toadd_fp_prod_sign,
298	                               mul_toadd_fp_prod_exp ,
299	                               mul_toadd_fp_prod_sig ,
300	                               mul_toadd_is_nan      ,
301	                               mul_toadd_is_inf      ,
302	                               mul_toadd_is_inv      ,
303	                               mul_toadd_overflow    ,
304	                               mul_toadd_add_another ,
305	                               mul_toadd_op          };
306	
307	  stream_fifo_pipe_true #(
308	    .DATA_WIDTH (LEN*2+PRECISION+7),
309	    .FIFO_DEPTH (1                )
310	  )
311	  multoadd_fifo_bits (
312	    .clk       (clk               ),
313	    .rst_n     (rst_n             ),
314	    .w_ready_o (multoadd_enq_ready),    
315	    .w_valid_i (multoadd_enq_valid),
316	    .w_data_i  (multoadd_enq_bits ),
317	    .r_valid_o (multoadd_deq_valid),
318	    .r_ready_i (multoadd_deq_ready),
319	    .r_data_o  (multoadd_deq_bits )
320	  );
321	
322	  wire                          from_mul_fp_prod_sign;
323	  wire [EXPWIDTH-1:0]           from_mul_fp_prod_exp ;
324	  wire [2*PRECISION-2:0]        from_mul_fp_prod_sig ;
325	  wire                          from_mul_is_nan      ;
326	  wire                          from_mul_is_inf      ;
327	  wire                          from_mul_is_inv      ;
328	  wire                          from_mul_overflow    ;
329	  wire [EXPWIDTH+PRECISION-1:0] from_mul_add_another ;
330	  //wire [2:0]                    from_mul_op          ;           
331	
332	  assign from_mul_fp_prod_sign = multoadd_deq_bits[LEN*2+PRECISION+6]                  ;
333	  assign from_mul_fp_prod_exp  = multoadd_deq_bits[LEN*2+PRECISION+5:LEN+PRECISION*2+6];
334	  assign from_mul_fp_prod_sig  = multoadd_deq_bits[LEN+PRECISION*2+5:LEN+7]            ;
335	  assign from_mul_is_nan       = multoadd_deq_bits[LEN+6]                              ;
336	  assign from_mul_is_inf       = multoadd_deq_bits[LEN+5]                              ;
337	  assign from_mul_is_inv       = multoadd_deq_bits[LEN+4]                              ;
338	  assign from_mul_overflow     = multoadd_deq_bits[LEN+3]                              ;
339	  assign from_mul_add_another  = multoadd_deq_bits[LEN+2:3]                            ;
340	  //assign from_mul_op           = multoadd_deq_bits[2:0]                                ;
341	
342	  //add pipe
343	  wire                                   add_in_valid     ;
344	  wire                                   add_in_ready     ;
345	  wire [2:0]                             add_in_op        ;
346	  wire [EXPWIDTH+PRECISION-1:0]          add_in_a         ;
347	  wire [EXPWIDTH+PRECISION-1:0]          add_in_b         ;
348	  //wire [EXPWIDTH+PRECISION-1:0]          add_in_c         ;
349	  wire [2:0]                             add_in_rm        ;
350	`ifdef CTRLGEN
351	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] add_in_reg_index ;
352	  wire [`DEPTH_WARP-1:0]                 add_in_warp_id   ;
353	  wire [SOFTTHREAD-1:0]                  add_in_vec_mask  ;
354	  wire                                   add_in_wvd       ;
355	  wire                                   add_in_wxd       ;
