357	  wire [`DEPTH_WARP-1:0]                 add_out_warp_id  ;
358	  wire [SOFTTHREAD-1:0]                  add_out_vec_mask ;
359	  wire                                   add_out_wvd      ;
360	  wire                                   add_out_wxd      ;
361	`endif
362	  wire                                   add_out_valid    ;
363	  wire                                   add_out_ready    ;
364	  wire [EXPWIDTH+PRECISION-1:0]          add_out_result   ;
365	  wire [4:0]                             add_out_fflags   ;
366	
367	  assign toaddarb_out_ready = add_in_ready      ;
368	  assign add_in_valid       = toaddarb_out_valid;
369	
370	  assign add_in_a  = intoadd_deq_bits[LEN*3+2:LEN*2+3];
371	  assign add_in_b  = intoadd_deq_bits[LEN*2+2:LEN+3]  ;
372	  //assign add_in_c  = intoadd_deq_bits[LEN+2:3]        ;
373	  assign add_in_rm = intoadd_deq_bits[2:0]            ;
374	  assign add_in_op = toaddarb_out_op                  ;
