379	  assign add_in_warp_id   = toaddarb_out_ctrl[`DEPTH_WARP+SOFTTHREAD+1:SOFTTHREAD+2]                                        ;
380	  assign add_in_vec_mask  = toaddarb_out_ctrl[SOFTTHREAD+1:2]                                                               ;
381	  assign add_in_wvd       = toaddarb_out_ctrl[1]                                                                            ;
382	  assign add_in_wxd       = toaddarb_out_ctrl[0]                                                                            ;
383	`endif
384	
385	  fadd_pipe #(
386	    .EXPWIDTH   (EXPWIDTH  ),
387	    .PRECISION  (PRECISION ),
388	    .SOFTTHREAD (SOFTTHREAD),
389	    .HARDTHREAD (HARDTHREAD)
390	  )
391	  add_pipe (
392	    .clk                     (clk                  ),
393	    .rst_n                   (rst_n                ),
394	    .in_valid_i              (add_in_valid         ),
395	    .in_ready_o              (add_in_ready         ),
396	    .in_op_i                 (add_in_op            ),
397	    .in_a_i                  (add_in_a             ),
398	    .in_b_i                  (add_in_b             ),
399	    //.in_c_i                  (add_in_c             ),
400	    .in_rm_i                 (add_in_rm            ),
401	    .from_mul_fp_prod_sign_i (from_mul_fp_prod_sign),
402	    .from_mul_fp_prod_exp_i  (from_mul_fp_prod_exp ),
403	    .from_mul_fp_prod_sig_i  (from_mul_fp_prod_sig ),
404	    .from_mul_is_nan_i       (from_mul_is_nan      ),
405	    .from_mul_is_inf_i       (from_mul_is_inf      ),
406	    .from_mul_is_inv_i       (from_mul_is_inv      ),
407	    .from_mul_overflow_i     (from_mul_overflow    ),
408	    .from_mul_add_another_i  (from_mul_add_another ),
409	    //.from_mul_op_i           (from_mul_op          ),
410	`ifdef CTRLGEN
411	    .in_reg_index_i          (add_in_reg_index     ),
412	    .in_warp_id_i            (add_in_warp_id       ),
413	    .in_vec_mask_i           (add_in_vec_mask      ),
414	    .in_wvd_i                (add_in_wvd           ),
415	    .in_wxd_i                (add_in_wxd           ),
416	    .out_reg_index_o         (add_out_reg_index    ),
417	    .out_warp_id_o           (add_out_warp_id      ),
418	    .out_vec_mask_o          (add_out_vec_mask     ),
419	    .out_wvd_o               (add_out_wvd          ),
420	    .out_wxd_o               (add_out_wxd          ),
421	`endif
422	    .out_valid_o             (add_out_valid        ),
423	    .out_ready_i             (add_out_ready        ),
424	    .out_result_o            (add_out_result       ),
425	    .out_fflags_o            (add_out_fflags       )
426	  );
