428	  //output in_ready_o
429	  assign in_ready_o = is_addsub ? toaddarb_fifo_1_enq_ready : mul_in_ready;
430	
431	  //mul fifo(for output)
432	  wire           mul_fifo_enq_valid;
433	  wire           mul_fifo_enq_ready;
434	  wire           mul_fifo_deq_valid;
435	  wire           mul_fifo_deq_ready;
436	  wire [LEN+4:0] mul_fifo_enq_bits;
437	  wire [LEN+4:0] mul_fifo_deq_bits;
438	
439	  assign mul_fifo_enq_valid = mul_out_valid && (mul_toadd_op[2:0]==3'b010);
440	  assign mul_fifo_enq_bits  = {mul_out_result,mul_out_fflags}             ;
441	    
442	  stream_fifo_pipe_true #(
443	    .DATA_WIDTH (LEN+5),
444	    .FIFO_DEPTH (1    )
445	  )
446	  mul_fifo_bits (
447	    .clk       (clk               ),
448	    .rst_n     (rst_n             ),
449	    .w_ready_o (mul_fifo_enq_ready),    
450	    .w_valid_i (mul_fifo_enq_valid),
451	    .w_data_i  (mul_fifo_enq_bits ),
452	    .r_valid_o (mul_fifo_deq_valid),
453	    .r_ready_i (mul_fifo_deq_ready),
454	    .r_data_o  (mul_fifo_deq_bits )
455	  );
456	
457	`ifdef CTRLGEN
458	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:0] mul_fifo_deq_ctrl;
459	  
460	  stream_fifo_pipe_true #(
461	    .DATA_WIDTH (`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+2),
462	    .FIFO_DEPTH (1                                                   )
463	  )
464	  mul_fifo_ctrl (
465	    .clk       (clk                     ),
466	    .rst_n     (rst_n                   ),
467	    .w_ready_o (ctrl_w_ready_o[3]       ),    
468	    .w_valid_i (mul_fifo_enq_valid      ),
469	    .w_data_i  (toaddarb_fifo_0_enq_ctrl),
470	    .r_valid_o (ctrl_r_valid_o[3]       ),
471	    .r_ready_i (mul_fifo_deq_ready      ),
472	    .r_data_o  (mul_fifo_deq_ctrl       )
473	  );
474	`endif
475	
476	  //add fifo(for output)
477	  wire           add_fifo_enq_valid;
478	  wire           add_fifo_enq_ready;
479	  wire           add_fifo_deq_valid;
480	  wire           add_fifo_deq_ready;
481	  wire [LEN+4:0] add_fifo_enq_bits;
482	  wire [LEN+4:0] add_fifo_deq_bits;
483	
484	  assign add_fifo_enq_valid = add_out_valid                  ;
485	  assign add_out_ready      = add_fifo_deq_ready             ;
486	  assign add_fifo_enq_bits  = {add_out_result,add_out_fflags};
487	    
488	  stream_fifo_pipe_true #(
489	    .DATA_WIDTH (LEN+5),
490	    .FIFO_DEPTH (1    )
491	  )
492	  add_fifo_bits (
493	    .clk       (clk               ),
494	    .rst_n     (rst_n             ),
495	    .w_ready_o (add_fifo_enq_ready),    
496	    .w_valid_i (add_fifo_enq_valid),
497	    .w_data_i  (add_fifo_enq_bits ),
498	    .r_valid_o (add_fifo_deq_valid),
499	    .r_ready_i (add_fifo_deq_ready),
500	    .r_data_o  (add_fifo_deq_bits )
501	  );
502	
503	  assign mul_out_ready = (toaddarb_fifo_0_enq_ready && (mul_toadd_op[2]==1'b1)) || (mul_fifo_enq_ready && (mul_toadd_op[2:0]==3'b010));
504	
505	`ifdef CTRLGEN
506	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:0] add_fifo_enq_ctrl;
507	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:0] add_fifo_deq_ctrl;
508	
509	  assign add_fifo_enq_ctrl = {add_out_reg_index,
510	                              add_out_warp_id  ,
511	                              add_out_vec_mask ,
512	                              add_out_wvd      ,
513	                              add_out_wxd      };
514	
515	  stream_fifo_pipe_true #(
516	    .DATA_WIDTH (`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+2),
517	    .FIFO_DEPTH (1                                                   )
518	  )
519	  add_fifo_ctrl (
520	    .clk       (clk               ),
521	    .rst_n     (rst_n             ),
522	    .w_ready_o (ctrl_w_ready_o[4] ),    
523	    .w_valid_i (add_fifo_enq_valid),
524	    .w_data_i  (add_fifo_enq_ctrl),
525	    .r_valid_o (ctrl_r_valid_o[4] ),
526	    .r_ready_i (add_fifo_deq_ready),
527	    .r_data_o  (add_fifo_deq_ctrl )
528	  );
529	`endif
530	
531	  //output arbiter: mul_fifo has a higher priority
532	  wire [LEN-1:0] mul_fifo_result;
533	  wire [4:0]     mul_fifo_fflags;
534	  wire [LEN-1:0] add_fifo_result;
535	  wire [4:0]     add_fifo_fflags;
536	
537	  assign mul_fifo_deq_ready = out_ready_i                       ;
538	  assign add_fifo_deq_ready = !mul_fifo_enq_valid && out_ready_i;
539	  assign mul_fifo_result    = mul_fifo_deq_bits[LEN+4:5]        ;
540	  assign mul_fifo_fflags    = mul_fifo_deq_bits[4:0]            ;
541	  assign add_fifo_result    = add_fifo_deq_bits[LEN+4:5]        ;
542	  assign add_fifo_fflags    = add_fifo_deq_bits[4:0]            ;
543	  
544	  assign out_result_o = mul_fifo_deq_valid ? mul_fifo_result : add_fifo_result;
545	  assign out_fflags_o = mul_fifo_deq_valid ? mul_fifo_fflags : add_fifo_fflags;
546	  assign out_valid_o  = mul_fifo_deq_valid || add_fifo_deq_valid              ;
547	
548	`ifdef CTRLGEN
549	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] add_fifo_reg_index;
550	  wire [`DEPTH_WARP-1:0]                 add_fifo_warp_id  ;
551	  wire [SOFTTHREAD-1:0]                  add_fifo_vec_mask ;
552	  wire                                   add_fifo_wvd      ;
553	  wire                                   add_fifo_wxd      ;
554	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] mul_fifo_reg_index;
555	  wire [`DEPTH_WARP-1:0]                 mul_fifo_warp_id  ;
556	  wire [SOFTTHREAD-1:0]                  mul_fifo_vec_mask ;
557	  wire                                   mul_fifo_wvd      ;
558	  wire                                   mul_fifo_wxd      ;
559	
560	  assign add_fifo_reg_index = add_fifo_deq_ctrl[`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:`DEPTH_WARP+SOFTTHREAD+2];
561	  assign add_fifo_warp_id   = add_fifo_deq_ctrl[`DEPTH_WARP+SOFTTHREAD+1:SOFTTHREAD+2]                                        ;
562	  assign add_fifo_vec_mask  = add_fifo_deq_ctrl[SOFTTHREAD+1:2]                                                               ;
563	  assign add_fifo_wvd       = add_fifo_deq_ctrl[1]                                                                            ;
564	  assign add_fifo_wxd       = add_fifo_deq_ctrl[0]                                                                            ;
565	  assign mul_fifo_reg_index = mul_fifo_deq_ctrl[`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP+SOFTTHREAD+1:`DEPTH_WARP+SOFTTHREAD+2];
566	  assign mul_fifo_warp_id   = mul_fifo_deq_ctrl[`DEPTH_WARP+SOFTTHREAD+1:SOFTTHREAD+2]                                        ;
567	  assign mul_fifo_vec_mask  = mul_fifo_deq_ctrl[SOFTTHREAD+1:2]                                                               ;
568	  assign mul_fifo_wvd       = mul_fifo_deq_ctrl[1]                                                                            ;
569	  assign mul_fifo_wxd       = mul_fifo_deq_ctrl[0]                                                                            ;
570	
571	  assign out_reg_index_o = mul_fifo_deq_valid ? mul_fifo_reg_index : add_fifo_reg_index;
572	  assign out_warp_id_o   = mul_fifo_deq_valid ? mul_fifo_warp_id   : add_fifo_warp_id  ;
573	  assign out_vec_mask_o  = mul_fifo_deq_valid ? mul_fifo_vec_mask  : add_fifo_vec_mask ;
574	  assign out_wvd_o       = mul_fifo_deq_valid ? mul_fifo_wvd       : add_fifo_wvd      ;
575	  assign out_wxd_o       = mul_fifo_deq_valid ? mul_fifo_wxd       : add_fifo_wxd      ;
576	`endif
577	
578	endmodule
579	
580	`undef CTRLGEN
581

